<?phpnamespace App\Actions\Auth;use App\Models\User;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;class AuthenticateUser{    /**     * Verify a set of credentials and issue an API token for the owner.     *     * An unknown email and a wrong password fail identically so the response     * cannot be used to discover which addresses hold an account.     *     * @return array{user: User, token: string}     *     * @throws ValidationException     */    public function handle(string $email, string $password, string $deviceName): array    {        $user = User::where('email', $email)->first();        if (! $user || ! Hash::check($password, $user->password)) {            throw ValidationException::withMessages([                'email' => __('auth.failed'),            ]);        }        return [            'user' => $user,            'token' => $user->createToken($deviceName)->plainTextToken,        ];    }}